const ahora = new Date();

const resultado = [];

for (const item of $input.all()) {

  const datos = item.json;

  // Normalizar estado
  const estado = String(
    datos.Estado ??
    datos.estado ??
    ''
  ).trim().toLowerCase();

  // Solo nos interesan tutorías ASIGNADAS
  if (estado !== 'asignada') {
    continue;
  }

  // Obtener fecha/hora de creación
  const fechaCreacion =
    datos.Hora_Creacion ??
    datos.Hora_Creación ??
    datos.Fecha_Hora_Creacion ??
    datos.Fecha_Hora_Creación ??
    datos['Hora de creación'] ??
    datos['Hora de Creacion'];

  if (!fechaCreacion) {
    continue;
  }

  const fecha = new Date(fechaCreacion);

  // Verificar fecha válida
  if (isNaN(fecha.getTime())) {
    continue;
  }

  // Diferencia en minutos
  const diferenciaMs = ahora.getTime() - fecha.getTime();
  const diferenciaMinutos = diferenciaMs / (1000 * 60);

  // Más de 45 minutos sin confirmar
  if (diferenciaMinutos > 45) {

    resultado.push({
      json: {
        ...datos,
        minutos_retraso: Math.floor(diferenciaMinutos),
        fecha_evaluacion: ahora.toISOString()
      }
    });

  }
}

return resultado;

const tutorias = $input.all();

const ids = tutorias.map(item => {
  const datos = item.json;

  return (
    datos.ID_Tutoria ??
    datos.Id_Tutoria ??
    datos.ID ??
    datos.id ??
    'SIN_ID'
  );
});

const detalle = tutorias.map(item => {

  const datos = item.json;

  const id =
    datos.ID_Tutoria ??
    datos.Id_Tutoria ??
    datos.ID ??
    datos.id ??
    'SIN_ID';

  const materia =
    datos.Materia ??
    datos.materia ??
    'Sin materia';

  const estado =
    datos.Estado ??
    datos.estado ??
    'Asignada';

  const minutos =
    datos.minutos_retraso ??
    0;

  return `• ${id} — ${materia} — ${estado} — ${minutos} min`;
});

const mensaje = 
`🚨 ATENCIÓN: Tutorías sin confirmar

Las siguientes tutorías llevan más de 45 minutos en estado "Asignada":

${detalle.join('\n')}

📋 IDs detectados:
${ids.join(', ')}

Favor verificar con el tutor/estudiante.

⏱️ Reporte generado automáticamente por TutorBot.`;

return [
  {
    json: {
      cantidad: tutorias.length,
      ids,
      mensaje
    }
  }
];
